html {
  overscroll-behavior: none;
}

/*
 * Overlay/panel enter animations.
 *
 * tw-animate-css's `enter`/`exit` keyframes also declare `filter: blur(...)`.
 * Even when the blur resolves to 0 that pushes the element through the filter
 * pipeline for the whole animation, which is expensive on a full-viewport
 * overlay or a full-height sheet panel. These keyframes touch only `opacity`
 * and `translate`, both of which the compositor can animate on its own.
 */
@keyframes overlay-fade-in {
  from {
    opacity: 0;
  }
}

@keyframes overlay-fade-out {
  to {
    opacity: 0;
  }
}

@keyframes sheet-slide-in {
  from {
    opacity: 0;
    translate: var(--sheet-slide-x, 0) var(--sheet-slide-y, 0);
  }
}

@keyframes sheet-slide-out {
  to {
    opacity: 0;
    translate: var(--sheet-slide-x, 0) var(--sheet-slide-y, 0);
  }
}

/*
 * Reserve the scrollbar gutter permanently. Radix's modal scroll lock
 * (react-remove-scroll) hides the document scrollbar and compensates with a
 * `margin-right` on <body>, which relayouts the whole document as a sheet or
 * dialog opens. With a stable gutter the width never changes, so the
 * compensation is not only unnecessary but would itself shift the page.
 */
@supports (scrollbar-gutter: stable) {
  html {
    scrollbar-gutter: stable;
  }

  html body[data-scroll-locked] {
    margin-right: 0 !important;
    padding-right: 0 !important;
    --removed-body-scroll-bar-size: 0px;
  }
}

/* Etiqueta de trabajo en curso: barrido de luz sobre el texto, sin cambiar su caja. */
@keyframes shimmer-text {
  from {
    background-position: 200% 0;
  }
  to {
    background-position: -200% 0;
  }
}

/* Entrada escalonada de filas en trazas y resultados de IA. */
@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Resplandor que se desplaza dentro del lienzo mientras se genera media. */
@keyframes generation-glow {
  0%,
  100% {
    transform: translate3d(-12%, -8%, 0) scale(1);
  }
  50% {
    transform: translate3d(12%, 8%, 0) scale(1.15);
  }
}

@keyframes spinner-fade {
  0%,
  39%,
  100% {
    opacity: 0.25;
  }

  40% {
    opacity: 1;
  }
}

.disable-transitions * {
  transition: none !important;
}

[data-print-root] {
  display: none;
}

@media print {
  @page {
    size: Letter;
    margin: 0;
  }

  html,
  body {
    width: 8.5in !important;
    height: 11in !important;
    margin: 0 !important;
    overflow: hidden !important;
  }

  body > *:not([data-print-root]) {
    display: none !important;
  }

  [data-print-root] {
    display: block !important;
    width: 8.5in !important;
    height: 11in !important;
    margin: 0 !important;
    overflow: hidden !important;
    background: white !important;
  }

  [data-print-root] [data-print-paper] {
    width: 8.5in !important;
    height: 11in !important;
    margin: 0 !important;
    box-shadow: none !important;
  }

  [data-print-root] [data-print-paper],
  [data-print-root] [data-print-paper] * {
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }
}

