                  </SelectContent>
                </Select>
              </Field>
              <Field>
                <FieldLabel htmlFor="support-subject">
                  Asunto{" "}
                  <span aria-hidden="true" className="text-destructive">
                    *
                  </span>
                  <span className="sr-only"> obligatorio</span>
                </FieldLabel>
                <Input
                  aria-required="true"
                  id="support-subject"
                  maxLength={250}
                  onChange={(event) =>
                    setValues((current) => ({
                      ...current,
                      subject: event.target.value,
                    }))
                  }
                  placeholder="Ej. No puedo publicar en Instagram"
                  value={values.subject}
                />
                <FieldDescription>
                  Usa una frase breve para reconocer el caso después.
                </FieldDescription>
              </Field>
              <Field>
                <FieldLabel htmlFor="support-description">
                  Descripción{" "}
                  <span aria-hidden="true" className="text-destructive">
                    *
                  </span>
                  <span className="sr-only"> obligatorio</span>
                </FieldLabel>
                <Textarea
                  aria-required="true"
                  id="support-description"
                  maxLength={5000}
                  onChange={(event) =>
                    setValues((current) => ({
                      ...current,
                      description: event.target.value,
                    }))
                  }
                  placeholder="Qué estabas haciendo, qué esperabas que ocurriera y qué ocurrió en su lugar."
                  rows={6}
                  value={values.description}
                />
              </Field>
            </FieldGroup>
          </div>
          <SheetFooter className="flex-row justify-end border-t">
            <Button
              disabled={pending}
              onClick={close}
              type="button"
              variant="brand-secondary"
            >
              <X data-icon="inline-start" /> Cancelar
