"use client"

import { useCallback, useEffect, useState } from "react"
import { Area, CartesianGrid, ComposedChart, XAxis } from "recharts"
import {
  BadgeDollarSign,
  CircleAlert,
  Receipt,
  RotateCcw,
  ShieldX,
  Wallet,
} from "lucide-react"

import { adminPaymentReportApi, ApiError } from "@workspace/api-client"
import type {
  AdminPaymentReport,
  AdminPaymentReportProduct,
  AdminPaymentReportRange,
  AdminPaymentReportStatusRow,
} from "@workspace/contracts"
import { Badge } from "@workspace/ui/components/badge"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@workspace/ui/components/card"
import { CardGrid } from "@workspace/ui/components/card-grid"
import {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@workspace/ui/components/chart"
import { CollectionHeader } from "@workspace/ui/components/collection-header"
import { DataTableFilter } from "@workspace/ui/components/data-table-controls"
import { EmptyState } from "@workspace/ui/components/empty-state"
import { MetricCard } from "@workspace/ui/components/metric-card"
import { PageLoading } from "@workspace/ui/components/page-loading"
import { RetryButton } from "@workspace/ui/components/retry-button"
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@workspace/ui/components/table"
import { TableEmptyRow } from "@workspace/ui/components/table-empty-row"

const rangeLabel: Record<AdminPaymentReportRange, string> = {
  "30d": "Últimos 30 días",
  "90d": "Últimos 90 días",
  "12m": "Últimos 12 meses",
}

const statusLabel: Record<AdminPaymentReportStatusRow["status"], string> = {
  paid: "Pagado",
  pending: "Pendiente",
  partially_refunded: "Reembolso parcial",
  refunded: "Reembolsado",
  failed: "Fallido",
}

const statusVariant: Record<
  AdminPaymentReportStatusRow["status"],
  "success" | "info" | "warning" | "secondary" | "destructive"
> = {
  paid: "success",
  pending: "info",
  partially_refunded: "warning",
  refunded: "secondary",
  failed: "destructive",
}

const chartConfig = {
  net: { label: "Neto", color: "var(--chart-1)" },
} satisfies ChartConfig

function money(minor: number, currency: string) {
  return new Intl.NumberFormat("es-EC", {
    currency,
    style: "currency",
  }).format(minor / 100)
}

function periodLabel(period: string) {
  const parts = period.split("-").map(Number)
  const [year, month, day] = parts
  if (!year || !month) return period
  const date = new Date(Date.UTC(year, month - 1, day ?? 1))
  return new Intl.DateTimeFormat("es-EC", {
    ...(day ? { day: "numeric", month: "short" } : { month: "short", year: "numeric" }),
    timeZone: "UTC",
  }).format(date)
}

export function AdminPaymentReportPage() {
  const [report, setReport] = useState<AdminPaymentReport | null>(null)
  const [range, setRange] = useState<AdminPaymentReportRange>("30d")
  const [productType, setProductType] =
    useState<AdminPaymentReportProduct>("all")
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState(false)
  const [forbidden, setForbidden] = useState(false)

  const load = useCallback(async () => {
    setIsLoading(true)
    setLoadError(false)
    try {
      setReport(await adminPaymentReportApi.get({ productType, range }))
      setForbidden(false)
    } catch (error) {
      if (error instanceof ApiError && error.status === 403) {
        setForbidden(true)
        return
      }
      console.error("Admin payment report request failed", error)
      setLoadError(true)
    } finally {
      setIsLoading(false)
    }
  }, [productType, range])

  useEffect(() => {
    void load()
  }, [load])

  if (forbidden) {
    return (
      <EmptyState
        description="Tu cuenta no tiene permisos para consultar el reporte de pagos."
        icon={ShieldX}
        title="Acceso restringido"
      />
    )
  }

  if (isLoading && !report) {
    return <PageLoading aria-label="Cargando reporte de pagos" />
  }

  if (loadError || !report) {
    return (
      <EmptyState
        action={<RetryButton onClick={() => void load()} />}
        description="No fue posible calcular el reporte de pagos."
        icon={CircleAlert}
        title="No pudimos cargar esta sección"
      />
    )
  }

  const { currency, metrics } = report
  const series = report.series.map((point) => ({
    label: periodLabel(point.period),
    net: point.netMinor / 100,
  }))

  return (
    <div className="flex flex-col gap-4">
      <CollectionHeader
        description="Cobros liquidados, reembolsos y facturación por producto en el periodo seleccionado."
        title="Reporte de pagos"
      />
      <div className="flex flex-wrap items-center gap-3">
        <DataTableFilter
          ariaLabel="Seleccionar rango"
          label="Rango"
          onValueChange={(value) => setRange(value as AdminPaymentReportRange)}
          options={[
            { label: rangeLabel["30d"], value: "30d" },
            { label: rangeLabel["90d"], value: "90d" },
            { label: rangeLabel["12m"], value: "12m" },
          ]}
          value={range}
        />
        <DataTableFilter
          ariaLabel="Filtrar por producto"
          label="Producto"
          onValueChange={(value) =>
            setProductType(value as AdminPaymentReportProduct)
          }
          options={[
            { label: "Todos", value: "all" },
            { label: "Planes", value: "plan" },
            { label: "Créditos", value: "credits" },
          ]}
          value={productType}
        />
        <p className="text-sm text-muted-foreground">
          Moneda {currency}
          {report.currencies.length > 1
            ? ` · ${report.currencies.length - 1} moneda(s) más sin agregar`
            : ""}
        </p>
      </div>

      <CardGrid>
        <MetricCard
          description="Cobros liquidados"
          icon={BadgeDollarSign}
          label="Bruto"
          value={money(metrics.grossMinor, currency)}
        />
        <MetricCard
          description="Bruto menos reembolsos"
          icon={Wallet}
          label="Neto"
          value={money(metrics.netMinor, currency)}
        />
        <MetricCard
          description={`${metrics.refundedCount} pagos con devolución`}
          icon={RotateCcw}
          label="Reembolsado"
          value={money(metrics.refundedMinor, currency)}
        />
        <MetricCard
          description={`${metrics.paidCount} pagados · ${metrics.pendingCount} pendientes · ${metrics.failedCount} fallidos`}
          icon={Receipt}
          label="Ticket medio"
          value={money(metrics.averageTicketMinor, currency)}
        />
      </CardGrid>

      <Card variant="subtle">
        <CardHeader>
          <CardTitle className="leading-none">Evolución</CardTitle>
          <CardDescription>
            Importe neto liquidado · {rangeLabel[report.range].toLowerCase()}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {series.length ? (
            <ChartContainer className="aspect-auto h-64 w-full" config={chartConfig}>
              <ComposedChart data={series} margin={{ top: 0 }}>
                <defs>
                  <linearGradient id="fillNet" x1="0" x2="0" y1="0" y2="1">
                    <stop
                      offset="5%"
                      stopColor="var(--color-net)"
                      stopOpacity={0.36}
                    />
                    <stop
                      offset="95%"
                      stopColor="var(--color-net)"
                      stopOpacity={0.04}
                    />
                  </linearGradient>
                </defs>
                <CartesianGrid strokeOpacity={0.5} vertical={false} />
                <XAxis
                  axisLine={false}
                  dataKey="label"
                  minTickGap={32}
                  tickLine={false}
                  tickMargin={8}
                />
                <ChartTooltip
                  content={<ChartTooltipContent className="w-44" indicator="line" />}
                  cursor={false}
                />
                <Area
                  dataKey="net"
                  dot={false}
                  fill="url(#fillNet)"
                  fillOpacity={1}
                  stroke="var(--color-net)"
                  strokeWidth={1.25}
                  type="natural"
                />
              </ComposedChart>
            </ChartContainer>
          ) : (
            <EmptyState
              description="No hay cobros liquidados en el periodo seleccionado."
              icon={BadgeDollarSign}
              title="Sin movimientos"
            />
          )}
        </CardContent>
      </Card>

      <div className="grid gap-4 lg:grid-cols-2">
        <Card variant="subtle">
          <CardHeader>
            <CardTitle className="text-base">Por producto</CardTitle>
            <CardDescription>
              Productos con mayor facturación del periodo.
            </CardDescription>
          </CardHeader>
          <CardContent className="px-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Producto</TableHead>
                  <TableHead className="hidden sm:table-cell">Pagos</TableHead>
                  <TableHead className="text-right">Bruto</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {report.byProduct.length ? (
                  report.byProduct.map((row) => (
                    <TableRow key={`${row.productType}-${row.label}`}>
                      <TableCell>
                        <div className="flex min-w-40 flex-col">
                          <span className="font-medium">{row.label}</span>
                          <span className="text-xs text-muted-foreground">
                            {row.productType === "plan" ? "Plan" : "Créditos"}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell className="hidden text-muted-foreground sm:table-cell">
                        {row.count}
                      </TableCell>
                      <TableCell className="text-right">
                        {money(row.grossMinor, currency)}
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableEmptyRow
                    colSpan={3}
                    description="Sin cobros liquidados en este periodo."
                    title="Sin datos"
                  />
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>

        <Card variant="subtle">
          <CardHeader>
            <CardTitle className="text-base">Por estado</CardTitle>
            <CardDescription>
              Incluye pendientes y fallidos, que no suman al bruto.
            </CardDescription>
          </CardHeader>
          <CardContent className="px-0">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Estado</TableHead>
                  <TableHead className="hidden sm:table-cell">Pagos</TableHead>
                  <TableHead className="text-right">Importe</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {report.byStatus.length ? (
                  report.byStatus.map((row) => (
                    <TableRow key={row.status}>
                      <TableCell>
                        <Badge variant={statusVariant[row.status]}>
                          {statusLabel[row.status]}
                        </Badge>
                      </TableCell>
                      <TableCell className="hidden text-muted-foreground sm:table-cell">
                        {row.count}
                      </TableCell>
                      <TableCell className="text-right">
                        {money(row.amountMinor, currency)}
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableEmptyRow
                    colSpan={3}
                    description="Sin pagos registrados en este periodo."
                    title="Sin datos"
                  />
                )}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      </div>

      <Card variant="subtle">
        <CardHeader>
          <CardTitle className="text-base">
            Espacios con mayor facturación
          </CardTitle>
          <CardDescription>
            Los cinco espacios de trabajo que más aportaron en el periodo.
          </CardDescription>
        </CardHeader>
        <CardContent className="px-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Espacio de trabajo</TableHead>
                <TableHead className="hidden sm:table-cell">Pagos</TableHead>
                <TableHead className="text-right">Bruto</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {report.topWorkspaces.length ? (
                report.topWorkspaces.map((row) => (
                  <TableRow key={row.workspaceId}>
                    <TableCell className="font-medium">
                      {row.workspaceName}
                    </TableCell>
                    <TableCell className="hidden text-muted-foreground sm:table-cell">
                      {row.count}
                    </TableCell>
                    <TableCell className="text-right">
                      {money(row.grossMinor, currency)}
                    </TableCell>
                  </TableRow>
                ))
              ) : (
                <TableEmptyRow
                  colSpan={3}
                  description="Sin cobros liquidados en este periodo."
                  title="Sin datos"
                />
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>
    </div>
  )
}
