export function AdminNotificationsPage() {
  const [announcements, setAnnouncements] = useState<AdminAnnouncement[]>([])
  const [metrics, setMetrics] = useState<AdminAnnouncementMetrics>(emptyMetrics)
  const [total, setTotal] = useState(0)
  const [query, setQuery] = useState("")
  const [status, setStatus] = useState<"all" | "draft" | "published">("all")
  const [page, setPage] = useState(1)
  const [isLoading, setIsLoading] = useState(true)
  const [loadError, setLoadError] = useState(false)
  const [forbidden, setForbidden] = useState(false)
  const [sheetOpen, setSheetOpen] = useState(false)
  const [editing, setEditing] = useState<AdminAnnouncement | null>(null)
  const [pending, setPending] = useState(false)
  const [deleting, setDeleting] = useState<AdminAnnouncement | null>(null)

  const load = useCallback(async () => {
    setIsLoading(true)
    setLoadError(false)
    try {
      const response = await adminNotificationsApi.list({
        limit: pageSize,
        page,
        ...(query.trim() ? { q: query.trim() } : {}),
        ...(status === "all" ? {} : { status }),
      })
      setAnnouncements(response.announcements)
      setMetrics(response.metrics)
      setTotal(response.total)
      setForbidden(false)
    } catch (error) {
      if (error instanceof ApiError && error.status === 403) {
        setForbidden(true)
        return
      }
      console.error("Admin announcements request failed", error)
      setLoadError(true)
    } finally {
      setIsLoading(false)
    }
  }, [page, query, status])

  useEffect(() => {
    const timer = setTimeout(() => void load(), query ? 300 : 0)
    return () => clearTimeout(timer)
  }, [load, query])

  const pageCount = Math.max(1, Math.ceil(total / pageSize))
  const safePage = Math.min(page, pageCount)
  const rangeStart = total ? (safePage - 1) * pageSize + 1 : 0
  const rangeEnd = total ? rangeStart + announcements.length - 1 : 0
  const hasFilters = Boolean(query || status !== "all")

  async function save(values: UpsertAdminAnnouncementInput) {
    setPending(true)
    try {
      if (editing) await adminNotificationsApi.update(editing.id, values)
      else await adminNotificationsApi.create(values)
      await load()
      toast.success(
        values.publish ? "Anuncio publicado." : "Borrador guardado."
      )
      return true
    } catch (error) {
      console.error("Announcement save failed", error)
      toast.error("No pudimos guardar el anuncio. Inténtalo de nuevo.")
      return false
    } finally {
      setPending(false)
    }
  }

  async function remove() {
    if (!deleting) return
    setPending(true)
    try {
      await adminNotificationsApi.remove(deleting.id)
      setDeleting(null)
      await load()
      toast.success("Anuncio eliminado.")
    } catch (error) {
      console.error("Announcement delete failed", error)
      toast.error("No pudimos eliminar el anuncio.")
    } finally {
      setPending(false)
    }
  }

  if (forbidden) {
    return (
      <EmptyState
        description="Tu cuenta no tiene permisos para administrar los anuncios de la plataforma."
        icon={ShieldX}
        title="Acceso restringido"
      />
    )
  }

  if (isLoading && !announcements.length && !loadError) {
    return <PageLoading aria-label="Cargando anuncios" />
  }

  if (loadError) {
    return (
      <EmptyState
        action={<RetryButton onClick={() => void load()} />}
        description="No fue posible cargar los anuncios."
        icon={Megaphone}
        title="No pudimos cargar esta sección"
      />
    )
  }

  return (
    <>
      <div className="flex flex-col gap-4">
        <CollectionHeader
          description="Avisos manuales que aparecen en la campana del Portal de los clientes."
          title="Anuncios"
        />
        <CardGrid>
          <MetricCard
            description="Visibles en el Portal"
            icon={BellRing}
            label="Publicados"
            value={metrics.published}
          />
          <MetricCard
            description="Sin publicar todavía"
            icon={FileText}
            label="Borradores"
            value={metrics.drafts}
          />
          <MetricCard
            description="Dirigidos a un espacio o persona"
            icon={Target}
            label="Segmentados"
            value={metrics.targeted}
          />
          <MetricCard
            description="Anuncios abiertos por clientes"
            icon={Eye}
            label="Lecturas"
            value={metrics.reads}
          />
        </CardGrid>
        <Card variant="subtle">
          <DataTableHeader
            action={
              <Button
                onClick={() => {
                  setEditing(null)
                  setSheetOpen(true)
                }}
                size="sm"
                type="button"
              >
                <Plus data-icon="inline-start" /> Nuevo anuncio
              </Button>
            }
            search={{
              ariaLabel: "Buscar anuncios",
              onChange: (value) => {
                setQuery(value)
                setPage(1)
              },
              placeholder: "Buscar por título o mensaje...",
              value: query,
            }}
          />
          <CardContent className="flex flex-col gap-4 px-0">
            <DataTableToolbar
              actions={
                hasFilters ? (
                  <Button
                    onClick={() => {
                      setQuery("")
                      setStatus("all")
                      setPage(1)
                    }}
                    size="sm"
                    type="button"
                    variant="outline"
                  >
                    <X /> Limpiar
                  </Button>
                ) : undefined
              }
            >
              <DataTableFilter
                ariaLabel="Filtrar por estado"
                label="Estado"
                onValueChange={(value) => {
                  setStatus(value as "all" | "draft" | "published")
                  setPage(1)
                }}
                options={[
                  { label: "Todos", value: "all" },
                  { label: "Publicados", value: "published" },
                  { label: "Borradores", value: "draft" },
                ]}
                value={status}
              />
            </DataTableToolbar>
            <div>
              <Table>
