                        </TableCell>
                        <TableCell className="hidden text-muted-foreground lg:table-cell">
                          {announcement.readCount}
                        </TableCell>
                        <TableCell className="hidden text-muted-foreground lg:table-cell">
                          {formatDate(announcement.createdAt)}
                        </TableCell>
                        <TableCell className="text-right">
                          <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                              <Button
                                aria-label={`Acciones de ${announcement.title}`}
                                size="icon-sm"
                                variant="brand-secondary"
                              >
                                <EllipsisVertical />
                              </Button>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent align="end">
                              <DropdownMenuItem
                                onSelect={() => {
                                  setEditing(announcement)
                                  setSheetOpen(true)
                                }}
                              >
                                <Pencil /> Editar
                              </DropdownMenuItem>
                              <DropdownMenuSeparator />
                              <DropdownMenuItem
                                onSelect={() => setDeleting(announcement)}
                                variant="destructive"
                              >
                                <Trash2 /> Eliminar
                              </DropdownMenuItem>
                            </DropdownMenuContent>
                          </DropdownMenu>
                        </TableCell>
                      </TableRow>
                    ))
                  ) : (
                    <TableEmptyRow
                      colSpan={6}
                      description={
                        hasFilters
                          ? "Prueba con otro término o estado."
                          : "Publica un aviso para que tus clientes lo vean en el Portal."
                      }
                      title={
                        hasFilters
                          ? "No hay coincidencias"
                          : "Todavía no hay anuncios"
                      }
                    />
                  )}
                </TableBody>
              </Table>
            </div>
            <TablePagination
              canGoNext={safePage < pageCount}
              canGoPrevious={safePage > 1}
              itemLabel="anuncios"
              onNextPage={() =>
                setPage((current) => Math.min(current + 1, pageCount))
              }
              onPreviousPage={() =>
                setPage((current) => Math.max(current - 1, 1))
              }
              rangeEnd={rangeEnd}
              rangeStart={rangeStart}
              total={total}
            />
          </CardContent>
        </Card>
      </div>
      <AnnouncementSheet
        editing={editing}
        onOpenChange={setSheetOpen}
        onSubmit={save}
        open={sheetOpen}
        pending={pending}
      />
      <AlertDialog
        onOpenChange={(open) => (open ? null : setDeleting(null))}
        open={Boolean(deleting)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Eliminar anuncio</AlertDialogTitle>
            <AlertDialogDescription>
              Se elimina «{deleting?.title}» y su historial de lecturas. Esta
              acción no se puede deshacer.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={pending}>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              disabled={pending}
              onClick={(event) => {
                event.preventDefault()
                void remove()
              }}
            >
              {pending ? <Spinner data-icon="inline-start" /> : <Trash2 data-icon="inline-start" />}
              Eliminar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
