import { PLAN } from "@/constants/plans";
import { APP_URL, getSite, type SitePlan } from "@/lib/zapi";

/**
 * Los planes salen del Admin. Un plan de Zapi es un registro por periodo, así
 * que mensual y anual se emparejan por nombre para alimentar el conmutador del
 * bloque de precios. Sin datos de la API se conserva el contenido por defecto
 * de la plantilla, de modo que la página nunca aparece vacía.
 */
function toPlans(plans: SitePlan[]): PLAN[] {
    const byName = new Map<string, { monthly?: SitePlan; yearly?: SitePlan }>();
    for (const plan of plans) {
        const entry = byName.get(plan.name) ?? {};
        entry[plan.billingType === "yearly" ? "yearly" : "monthly"] = plan;
        byName.set(plan.name, entry);
    }

    return [...byName.entries()]
        .map(([name, entry]) => {
            const base = entry.monthly ?? entry.yearly;
            if (!base) return null;
            const monthly = (entry.monthly ?? base).priceMinor / 100;
            const yearly = entry.yearly
                ? entry.yearly.priceMinor / 100
                : Math.round(monthly * 12 * 0.88);
            return {
                id: base.slug,
                title: name,
                desc: base.description,
                monthlyPrice: monthly,
                annuallyPrice: yearly,
                badge: base.featured ? "Más elegido" : undefined,
                buttonText: base.isFree ? "Empezar gratis" : `Elegir ${name}`,
                features: base.description
                    .split(/\\r?\\n|·/)
                    .map((line) => line.trim())
                    .filter(Boolean),
                link: `${APP_URL}/register?plan=${base.slug}`,
            } satisfies PLAN;
        })
        .filter((plan): plan is PLAN => plan !== null)
        .sort((a, b) => a.monthlyPrice - b.monthlyPrice);
}

const HomePage = async () => {
    const site = await getSite();
    const plans = site?.plans.length ? toPlans(site.plans) : undefined;

    return (
        <Wrapper className="py-20 relative">
            <Hero />
            <Companies />
            <Features />
            <Analysis />
            <Integration />
            <Pricing plans={plans} />
            <LanguageSupport />
            <CTA />
        </Wrapper>
    )
};

export default HomePage
''')
