import re, os, sys
from pathlib import Path

ROOT = Path("apps/web")
APP = ROOT / "app"

# 1. Rutas reales, con segmentos dinámicos como comodín
routes = []
for page in APP.rglob("page.tsx"):
    rel = page.relative_to(APP).parent.as_posix()
    segs = [s for s in rel.split("/") if s and not (s.startswith("(") and s.endswith(")"))]
    routes.append(segs if rel != "." else [])

def matches(href):
    segs = [s for s in href.strip("/").split("/") if s]
    for r in routes:
        catchall = any(s.startswith("[...") or s.startswith("[[...") for s in r)
        if not catchall and len(r) != len(segs):
            continue
        ok = True
        for i, rs in enumerate(r):
            if rs.startswith("[[...") or rs.startswith("[..."):
                ok = True; break
            if i >= len(segs): ok = False; break
            if rs.startswith("[") and rs.endswith("]"):
                continue
            if rs != segs[i]:
                ok = False; break
        if ok:
            return True
    return False

PATTERNS = [
    (r'href=["\'](?P<t>[^"\']+)["\']', "href"),
    (r'href:\s*["\'](?P<t>[^"\']+)["\']', "href:"),
    (r'router\.(?:push|replace)\(\s*["\'](?P<t>[^"\']+)["\']', "router"),
    (r'\bredirect\(\s*["\'](?P<t>[^"\']+)["\']', "redirect"),
]

findings = {"placeholder": [], "inexistente": [], "externa": []}
for f in list((ROOT/"app").rglob("*.tsx")) + list((ROOT/"features").rglob("*.tsx")) + \
         list((ROOT/"components").rglob("*.tsx")) + list((ROOT/"features").rglob("*.ts")):
    if "node_modules" in f.as_posix() or ".next" in f.as_posix():
        continue
    src = f.read_text(encoding="utf-8", errors="ignore")
    for line_no, line in enumerate(src.split("\n"), 1):
        for pat, kind in PATTERNS:
            for m in re.finditer(pat, line):
                t = m.group("t").strip()
                loc = f"{f.as_posix()}:{line_no}"
                if t in ("#", "", "/#") or t.startswith("#") and len(t) < 3:
                    findings["placeholder"].append((loc, kind, t))
                elif t.startswith("http"):
                    findings["externa"].append((loc, kind, t))
                elif t.startswith("/"):
                    clean = t.split("?")[0].split("#")[0]
                    if not matches(clean):
                        findings["inexistente"].append((loc, kind, t))

for name, items in findings.items():
    print(f"\n### {name.upper()} ({len(items)})")
    seen=set()
    for loc, kind, t in items:
        key=(t,loc.split('/')[-1])
        if key in seen: continue
        seen.add(key)
        print(f"  {t:52s} {kind:9s} {loc}")
